typedef void *Pointer;
typedef unsigned int MemSize;
typedef unsigned int MemFlags;

enum MemoryBlockTypes
{
    mbtFree = 0x00000000
};

enum MemoryAllocationFlags
{
    mafNone = 0x00,
    mafHigh = 0x01
};

struct MemFlagDWord
{
    MemFlags magic : 16;
    MemFlags heapid : 8;
    MemFlags flags : 8;
};

class MemBlockInfo
{
public:
    MemBlockInfo *prev;
    MemBlockInfo *next;
    MemBlockInfo *prevoftype;
    MemBlockInfo *nextoftype;
    MemSize size;
    MemFlagDWord flags;
    MemFlags blockid;
};

class Heap
{
    MemBlockInfo *fullhead;
    MemBlockInfo *fulltail;
    MemBlockInfo *usedhead;
    MemBlockInfo *usedtail;
    MemBlockInfo *freehead;
    MemBlockInfo *freetail;
    MemSize heapsize;
    Pointer heapstart;
    MemSize allocatedblocks;
    MemSize minalloc;
    MemSize minalign;
    MemSize lastalloc;
    MemFlags heapid;
    Pointer loblock;
    Pointer hiblock;
    bool locked;
    bool statsuptodate;

public:
    void AddHeapMemory(Pointer ptr, MemSize size);
    void FreeHeapMemory();
    MemSize HeaderSize() const;
    MemFlags GetHeapID() const { return heapid; }
    void SetBlockSentry(MemBlockInfo *block);
    Pointer Allocate(MemSize size, MemSize align, MemFlags flags,
                     const char *name, int line);
    void InitLoHi(Pointer lo, Pointer hi);
};

extern const char lowblock_name[];
extern const char highblock_name[];

asm(".equ FreeHeapMemory__4Heap, 0x002AB4D0");
asm(".equ HeaderSize__C4Heap, 0x002AB370");
asm(".equ SetBlockSentry__4HeapP12MemBlockInfo, 0x002AB678");
asm(".equ Allocate__4HeapUiUiUiPCci, 0x002AB530");
asm(".equ InitLoHi__4HeapPvT1, 0x002AB628");
asm(".equ lowblock_name, 0x004F90B0");
asm(".equ highblock_name, 0x004F90C0");

void Heap::AddHeapMemory(Pointer ptr, MemSize size)
{
    if (minalloc < 1) minalloc = 1;
    if (minalign < 1) minalign = 1;
    FreeHeapMemory();
    fullhead = (MemBlockInfo *)ptr;
    fullhead->size = size - HeaderSize();
    fullhead->flags.flags = mbtFree;
    fullhead->next = 0;
    fullhead->prev = 0;
    fullhead->nextoftype = 0;
    fullhead->prevoftype = 0;
    fulltail = fullhead;
    freehead = fullhead;
    freetail = fullhead;
    heapstart = ptr;
    heapsize = size;
    lastalloc = 1;
    SetBlockSentry(fullhead);
    fullhead->flags.magic = 0x7E07;
    fullhead->flags.heapid = GetHeapID();
    statsuptodate = false;
    loblock = Allocate(4, minalign, mafNone, lowblock_name, 0);
    hiblock = Allocate(4, minalign, mafHigh, highblock_name, 0);
    InitLoHi(loblock, hiblock);
}
